{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "자치구가 공설동물장묘시설을 만들 때 서울시의 비용 지원 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자치구가 공설동물장묘시설을 설치하는 경우 서울시는 예산의 범위에서 필요한 경비를 지원할 수 있다. 따라서 자치구는 서울시의 비용 지원을 받을 수 있다.",
          "b_ids": "동물보호:제30조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "공설동물장묘시설 이용자에게 사용료나 관리비를 받을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장 또는 구청장은 제1항 및 제2항에 따라 설치되는 공설동물장묘시설을 이용하는 시민에게 법 제71조제3항에 따라 사용료 또는 관리비를 부과할 수 있다. 따라서 시설 이용자에게 사용료나 관리비를 받을 수 있다.",
          "b_ids": "동물보호:제30조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
